2	
3	import jakarta.persistence.Entity;
4	import jakarta.persistence.EnumType;
5	import jakarta.persistence.Enumerated;
6	import jakarta.persistence.GeneratedValue;
7	import jakarta.persistence.GenerationType;
8	import jakarta.persistence.Id;
9	import jakarta.persistence.Table;
10	import org.hibernate.annotations.JdbcTypeCode;
11	import org.hibernate.type.SqlTypes;
12	
13	import java.util.Objects;
14	
15	/**
16	 * One Check a Transfer requires, and how that Check has answered it.
17	 *
18	 * <p>A Transfer's rows together are its Check Ledger, and they are written when the
19	 * Transfer is: the set of rows is fixed at request time, not a log that grows as parties
20	 * report things. The unique constraint on {@code (transfer_id, required_check)}
21	 * says the same in the table, and it is what will make a Check service's at-least-once
22	 * delivery safe to receive.
23	 *
24	 * <p><b>An unanswered Check has no Verdict, and the column is null.</b> The alternative —
25	 * a third {@code PENDING} constant on {@link Verdict}, which is the shape design decision
26	 * 8 sketched — would make "nobody has answered" one of the answers, and every reader would
27	 * then have to know which of the three is not really a Verdict. {@link
28	 * hu.bankmonitor.payments.transfers.TransferStatus} carries {@code PENDING} for the
29	 * opposite reason: a Transfer really is in that state. Nothing is in the state of having
30	 * given the null answer.
31	 *
32	 * <p><b>The Transfer is referenced by ID, not by association</b>, on {@code Transfer}'s own
33	 * precedent: a Transfer only ever leaves {@code PENDING} by a conditional update guarded on
34	 * the status it is leaving, and an association would offer a second way to reach one that
35	 * quietly skips that.
36	 *
37	 * <p><b>The identifier is surrogate rather than the pair that is unique</b>, on {@code
38	 * IdempotencyRecord}'s precedent: Spring Data decides between insert and merge from whether
39	 * the identifier is set, so an assigned key would turn every {@code save} into a
40	 * {@code SELECT} followed by an {@code UPDATE}. The uniqueness that matters is a named
41	 * constraint either way.
42	 *
43	 * <p>There is deliberately no mutator. Ticket 20 writes a Verdict as an update guarded on
44	 * the row still being unanswered, because two deliveries of the same Verdict have to leave
45	 * the Transfer advanced once; a setter would offer a second way to make that transition
46	 * that quietly is not atomic.
47	 */
48	@Entity
49	@Table(name = "check_ledger")
50	class CheckLedgerEntry {
51	
52		@Id
53		@GeneratedValue(strategy = GenerationType.IDENTITY)
54		private Long id;
55	
56		private Long transferId;
57	
58		// `check` is reserved in SQL, so the column this name produces is `required_check`.
59		@Enumerated(EnumType.STRING)
60		@JdbcTypeCode(SqlTypes.VARCHAR)
61		private Check requiredCheck;
62	
63		// If left unannotated, JPA stores the verdict by ordinal. See design decision 29.
64		@Enumerated(EnumType.STRING)
65		@JdbcTypeCode(SqlTypes.VARCHAR)
66		private Verdict verdict;
67	
68		protected CheckLedgerEntry() {
69			// required by JPA
70		}
71	
72		/**
73		 * A row in any state it can hold, which is what {@link LedgerDecision#decide} is
74		 * specified over and therefore has to be able to see.
75		 *
76		 * <p>Production never reaches this with a Verdict in hand — {@link #outstanding} is how
77		 * a row comes into being, and the answer arrives later as an update. That is the
78		 * distinction being drawn: constructing a row in a state is not the same operation as
79		 * <em>transitioning</em> one into it, and only the transition has a race to lose.
80		 */
81		CheckLedgerEntry(Long transferId, Check requiredCheck, Verdict verdict) {
82			this.transferId = Objects.requireNonNull(transferId, "a check is required of a transfer");
83			this.requiredCheck = Objects.requireNonNull(requiredCheck, "a ledger row is one check");
84			this.verdict = verdict;
85		}
86	
87		/** Opens a Check on a Transfer with nobody having answered it yet. */
88		static CheckLedgerEntry outstanding(Long transferId, Check requiredCheck) {
89			return new CheckLedgerEntry(transferId, requiredCheck, null);
90		}
91	
92		Long getId() {
93			return id;
94		}
95	
96		/** Whether this Check has said no — the one answer that ends a Transfer on its own. */
97		boolean isRejected() {
98			return verdict == Verdict.REJECTED;
99		}
100	
101		/** Whether anyone has answered this Check at all, either way. */
102		boolean isAnswered() {
103			return verdict != null;
104		}
105	}
