package hu.bankmonitor.payments.transfers;

import org.springframework.data.repository.Repository;

/**
 * The one way a {@link Transfer} comes into being, on an interface of its own so that
 * "exactly one class may write a Transfer" is a claim a rule can be pointed at.
 *
 * <p>Splitting it off {@link TransferRepository} costs an interface and buys the difference
 * between two kinds of access. Creating a Transfer is restricted, because a Transfer written
 * anywhere but {@link FundsReservation} would be {@code PENDING} against an empty Check
 * Ledger — the state the whole design is arranged to prevent, and the one
 * {@code NothingButTheReservationCreatesATransferTest} aims at this interface. Reading one,
 * and advancing one by a guarded update, are not restricted at all: the guard travels with
 * the statement, so a second caller cannot make the transition twice however it reached it.
 *
 * <p>Before ticket 20 both lived on {@code TransferRepository} and the rule was aimed there,
 * which held only while the reservation was the sole caller of anything about a Transfer.
 * The alternative — an allow-list of classes permitted to hold the repository — is a
 * structural claim degraded into a list every later ticket appends to.
 */
interface TransferCreation extends Repository<Transfer, Long> {

	/** Writes one Transfer, which is how a Transfer comes to exist. */
	Transfer save(Transfer transfer);
}

